//! Actual PrepareQuery/SourceSnapshot/public report and revision boundaries.
use super::*;use std::io;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_config;
fn setter_host()->(crate::runner_host::BuildHost,BuildRequest,PathBuf){let(mut host,mut request,root)=fixture("#define SETTER(T,v)\n/datum/setter_probe\n    var/charge\nSETTER(/datum/setter_probe, charge)\n/datum/setter_probe/proc/set_charge(value)\n    charge=value\n");let config="[lint.auto_tracked.lists]\ninclude=[\"/datum/setter_probe::charge\"]\n";std::fs::write(root.join("tools/ci/lint_scopes.toml"),report_config::with_overlay(config)).unwrap();for n in 0..140{std::fs::write(root.join(format!("code/filler_{n:03}.dm")),format!("/datum/setter_filler_{n:03}\n")).unwrap();}let intent=request.policy_inputs.as_mut().unwrap();intent.analysis_context=Some(AnalysisContext::OriginalAnalyze0290);intent.workspace_auxiliary=vec![crate::policy_request::WorkspaceAuxiliaryQuestion::SetterPublishes];run(&mut host,&request);(host,request,root)}
#[test]fn actual_original_setter_policy_reuses_existing_children_and_retracts_after_source_revision(){let(mut host,request,root)=setter_host();let queries=Arc::clone(host.query_db());let question=crate::policy_request::WorkspaceAuxiliaryQuestion::SetterPublishes;let first=current(&host,|snapshot|snapshot.with_original_semantic_policy_report(question,|data,_,_|{assert_eq!(data.sites().len(),2,"explicit false and inferred true are distinct old tuples");assert!(data.sites().iter().all(|site|site.rule=="no_publish"));Ok(data.sites().to_vec())}).unwrap());let bodies=queries.db().stats(dm_query::Kind(4)).computed;let policies=queries.db().stats(dm_query::Kind(12)).computed;current(&host,|snapshot|snapshot.with_original_semantic_policy_report(question,|data,_,_|{assert_eq!(data.sites(),first);Ok(())}).unwrap());assert_eq!(queries.db().stats(dm_query::Kind(4)).computed,bodies);assert_eq!(queries.db().stats(dm_query::Kind(12)).computed,policies);std::fs::write(root.join("code/probe.dm"),"#define SETTER(T,v)\n/datum/setter_probe\n    var/charge\nSETTER(/datum/setter_probe, charge)\n/datum/setter_probe/proc/set_charge(value)\n    charge=value\n    ..()\n").unwrap();run(&mut host,&request);current(&host,|snapshot|snapshot.with_original_semantic_policy_report(question,|data,_,_|{assert!(data.sites().is_empty(),"actual revised parent publish retracts both old sites");Ok(())}).unwrap());assert!(queries.db().stats(dm_query::Kind(12)).computed>policies);std::fs::write(root.join("code/probe.dm"),"#define SETTER(T,v)\n/datum/setter_probe\n    var/charge\nSETTER(/datum/setter_probe, charge)\n/datum/setter_probe/proc/set_charge(value)\n    charge=value\n").unwrap();std::fs::write(root.join("tools/ci/lint_scopes.toml"),report_config::with_overlay("[lint.auto_tracked.lists]\ninclude=[]\n[lint.setter_publishes]\nexempt_files=[\"code/probe.dm\"]\n")).unwrap();run(&mut host,&request);current(&host,|snapshot|snapshot.with_original_semantic_policy_report(question,|data,_,_|{assert_eq!(data.sites().len(),1,"config revision retracts inferred must=true while explicit must=false remains; old setter exemption is intentionally unused");Ok(())}).unwrap());}
#[test]fn actual_original_setter_role_refuses_foreign_querydb_and_preserves_first_writer_io_then_recovers(){let(host,_,root)=setter_host();let question=crate::policy_request::WorkspaceAuxiliaryQuestion::SetterPublishes;current(&host,|snapshot|{let workspace=snapshot.native_workspace.as_ref().unwrap();let capture=snapshot.workspace_semantic_inputs(question).unwrap();let guard=snapshot.workspace_native_read().unwrap();let foreign=crate::query_db::QueryDb::default();assert!(foreign.with_original_workspace_semantic_guard(workspace,&guard,capture,question,|_|Ok(())).is_err());assert!(snapshot.with_original_semantic_policy_report(crate::policy_request::WorkspaceAuxiliaryQuestion::UntrackedInputs,|_,_,_|Ok(())).is_err());struct Failed;impl std::io::Write for Failed{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}let lints=vec!["setter_publishes".into()];let actual=snapshot.write_native_workspace_semantic_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&lints,None,128,&snapshot.tree,&mut Failed).unwrap_err();assert_eq!(actual.raw_os_error(),Some(1450));let mut page=Vec::new();snapshot.write_native_workspace_semantic_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&lints,None,128,&snapshot.tree,&mut page).unwrap();let text=std::str::from_utf8(&page).unwrap();assert!(text.contains("hard_site")&&text.contains("setter_publishes"));assert!(snapshot.write_native_workspace_semantic_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&["setter_publishes".into(),"sem/reads".into()],None,128,&snapshot.tree,&mut Vec::new()).is_err());});}
